"""Small helpers shared by the PDF and Excel report builders."""
from __future__ import annotations

import re
import unicodedata
from datetime import datetime, timezone

DISCLAIMER = (
    "Generated by ScoutIQ. Scores, fair values and projections are model estimates from FIFA ratings and "
    "FBref season statistics, intended to support (not replace) scouting judgement."
)


def season_label(code) -> str:
    try:
        code = int(code)
        return f"20{code // 100:02d}/{code % 100:02d}"
    except (TypeError, ValueError):
        return "—"


def money(value) -> str:
    try:
        v = float(value)
    except (TypeError, ValueError):
        return "—"
    if v != v:
        return "—"
    sign = "-" if v < 0 else ""
    v = abs(v)
    if v >= 1e6:
        return f"{sign}€{v / 1e6:.1f}M"
    if v >= 1e3:
        return f"{sign}€{v / 1e3:.0f}K"
    return f"{sign}€{v:.0f}"


def number(value, digits: int = 1, suffix: str = "") -> str:
    try:
        v = float(value)
    except (TypeError, ValueError):
        return "—"
    return "—" if v != v else f"{v:.{digits}f}{suffix}"


def pdf_safe(text) -> str:
    """The built-in PDF fonts only cover Western characters: keep those, fold accents, replace the rest."""
    if text is None:
        return "—"
    out = []
    for ch in str(text):
        try:
            ch.encode("cp1252")
            out.append(ch)
        except UnicodeEncodeError:
            base = "".join(c for c in unicodedata.normalize("NFKD", ch) if not unicodedata.combining(c))
            out.append(base if base and base.isascii() else "?")
    return "".join(out).strip() or "—"


def file_slug(text: str, fallback: str = "report") -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", unicodedata.normalize("NFKD", str(text)).encode("ascii", "ignore").decode().lower()).strip("-")
    return slug or fallback


def generated_stamp() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")


PERCENTILE_LABELS = {
    "gls": "Goals / 90", "ast": "Assists / 90", "x_g": "xG / 90", "x_ag": "xAG / 90", "npx_g": "npxG / 90",
    "prg_c": "Progressive carries / 90", "prg_p": "Progressive passes / 90", "prg_r": "Progressive receptions / 90",
    "kp": "Key passes / 90", "1_3": "Passes into final third / 90", "ppa": "Passes into box / 90",
    "crs_pa": "Crosses into box / 90", "total_cmp": "Passes completed / 90", "total_cmppct": "Pass completion %",
    "expected_x_a": "xA / 90", "tackles_tkl": "Tackles / 90", "tackles_tkl_w": "Tackles won / 90",
    "int": "Interceptions / 90", "tkl_int": "Tackles + interceptions / 90", "clr": "Clearances / 90",
    "blocks_blocks": "Blocks / 90", "sca_sca90": "Shot-creating actions / 90", "gca_gca90": "Goal-creating actions / 90",
    "physic": "Physical rating (FIFA)", "performance_saves": "Saves / 90", "performance_savepct": "Save %", "performance_cspct": "Clean sheet %",
}


def percentile_label(key: str) -> str:
    stem = key.removeprefix("per_90_minutes_")
    if stem in PERCENTILE_LABELS:
        return PERCENTILE_LABELS[stem]
    return stem.replace("_", " ").strip().capitalize()
